{
  "title": "Monthly Rainfall",
  "body": "<figure><ml-embed ref="@tool:3fa9c21:out"></ml-embed><figcaption id="cap">Monthly rainfall over one year (mm).</figcaption></figure><section><h2>Three wettest months</h2><ol id="wettest"></ol><p id="total" class="total"></p><p id="err" class="err"></p></section>",
  "css": "body{font-family:sans-serif} figure{margin:0 0 16px} figcaption{font-size:.9em;color:#555;margin-top:6px;text-align:center} h2{font-size:1.1em;margin:0 0 8px} ol{margin:0 0 12px;padding-left:24px} li{margin:4px 0} .total{font-weight:bold;font-size:1.05em} .err{color:#b00020}",
  "scripts": [
    "try {
  const raw = ml.dereference('@tool:7be01d4:out');
  const lines = raw.trim().split(/\r?\n/).slice(1).filter(l => l.trim().length > 0);
  const rows = lines.map(l => {
    const parts = l.split(',');
    return { month: parts[0].trim().replace(/^"|"$/g, ''), mm: Number(parts[1]) };
  }).filter(r => !Number.isNaN(r.mm));
  const top = rows.slice().sort((a, b) => b.mm - a.mm).slice(0, 3);
  const total = rows.reduce((s, r) => s + r.mm, 0);
  const list = root.byId['wettest'];
  list.children = top.map(r => ({ tag: 'li', attrs: {}, text: `${r.month}: ${r.mm.toFixed(1)} mm`, children: [] }));
  root.byId['total'].text = `Yearly total: ${total.toFixed(1)} mm (${rows.length} months)`;
} catch (e) {
  root.byId['err'].text = 'Could not read the rainfall data.';
}"
  ]
}
